/** @purpose Load and save the todo list as a JSON file on disk. */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import type { Todo } from "./types";

function normalize(item: unknown, path: string): Todo {
  if (typeof item !== "object" || item === null || Array.isArray(item)) {
    throw new Error(`Corrupt todo file: ${path}`);
  }
  const rec = item as Record<string, unknown>;
  let completed: unknown = rec.completed;
  if (!("completed" in rec) && typeof rec.done === "boolean") {
    completed = rec.done;
  }
  const todo: Todo = {
    id: rec.id as number,
    title: rec.title as string,
    completed: completed as boolean,
  };
  if (rec.due !== undefined) todo.due = rec.due as string;
  return todo;
}

function serialize(t: Todo): Record<string, unknown> {
  const out: Record<string, unknown> = { id: t.id, title: t.title, completed: t.completed };
  if (t.due !== undefined) out.due = t.due;
  return out;
}

export function load(path: string): Todo[] {
  if (!existsSync(path)) return [];
  const raw = JSON.parse(readFileSync(path, "utf8")) as unknown;
  if (!Array.isArray(raw)) throw new Error(`Corrupt todo file: ${path}`);
  return raw.map((item) => normalize(item, path));
}

export function save(path: string, todos: Todo[]): void {
  writeFileSync(path, JSON.stringify(todos.map(serialize), null, 2) + "\n");
}

